fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // All three vectors must have the same length
    debug_assert!(s1.len() == s2.len() && s2.len() == s3.len());

    let n = s1.len();
    // Since 3*n is guaranteed to fit in an i32, it also fits in a usize on typical platforms.
    let mut res = Vec::with_capacity(3 * n);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}